\centering
\small
\begin{tabular}{lccc}
\toprule
\textbf{Metric} & \textbf{Sequential} & \textbf{Joint G-MFRM} & \textbf{Improv.} \\
\midrule
$\theta$ RMSE & $0.166 \pm 0.049$ & $0.083 \pm 0.024$ & $-50.1\%$ \\
$\theta$ $\tau$ & $0.882 \pm 0.117$ & $0.954 \pm 0.046$ & $+7.2$pp \\
$c_n$ RMSE & $1.349$ & $0.503$ & $-62.7\%$ \\
\bottomrule
\end{tabular}
\caption{Synthetic calibration at matched scale ($N = 8$, $I = 176$, $J = 9$, 20 seeds). Joint G-MFRM halves $\theta$-RMSE and reduces $c_n$-RMSE by 63\% relative to sequential estimation.}
\label{tab:synthetic_calibration}
\end{table}

